// crAuth GATE — generated into every client webhook by Tools/n8n/apply-auth-gate.py from
// Tools/n8n/auth/gate.js (+ token.js). Edit the sources, re-run the migration; never the copies.
//
// Verifies the Bearer capability token WITHOUT a database round-trip (HMAC, see token.js), then
// checks that every id the request names is owned by the token's install:
//   RULE.profiles  — body fields whose value(s) must be ⊆ claims.p   (sentinels ''/'-1' pass)
//   RULE.workflows — body fields whose value(s) must be ⊆ claims.w   (sentinels ''/'-1' pass)
//   RULE.appUser   — body fields that must EQUAL claims.u; a token WITHOUT a billing identity (u = null: the
//                    id is held by another install or was not bindable) can name none (R2, 2026-09-27)
//   RULE.appUserRequired — appUser fields that may not be empty/sentinel in session mode (Create WA/TG: an
//                    empty AppUserID skipped the channel count and let the dialog quota fail open)
//   RULE.legacy    — true: a request WITHOUT a token is admitted in `legacy` mode while
//                    CR_AUTH_COMPAT_UNTIL lies in the future (old clients); false: 401
// Output: the webhook item re-emitted — json AND binary: a Code node drops whatever it does not return,
// and a multipart upload's parts (Unity WWWForm files even its text fields there) live in `binary`
// (R3, 2026-09-27) — with `crAuth` = { ok, mode, reason, installId, appUserId, profiles, workflows,
// claimPending } so downstream nodes can read the verified identity. The gate sees `body` only, so
// ids that arrive as multipart parts are checked by the workflow after it decodes them.
// CRAUTH-TOKEN-BEGIN
const crAuth = (() => {
  const crypto = require('crypto');
  const b64u = (buf) => Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  const unb64u = (s) => Buffer.from(String(s).replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((String(s).length + 3) % 4), 'base64');
  const isIdList = (a) => Array.isArray(a) && a.every((x) => typeof x === 'string' && x.length > 0 && x.length <= 128);
  function sign(payload, secret) {
    if (!secret) throw new Error('crAuth: no signing secret');
    const p = b64u(JSON.stringify(payload));
    const sig = crypto.createHmac('sha256', secret).update('v1.' + p).digest();
    return 'v1.' + p + '.' + b64u(sig);
  }
  function verify(token, secrets, nowSec) {
    if (typeof token !== 'string' || !token) return { ok: false, reason: 'missing' };
    const parts = token.split('.');
    if (parts.length !== 3 || parts[0] !== 'v1' || !parts[1] || !parts[2]) return { ok: false, reason: 'malformed' };
    const given = unb64u(parts[2]);
    let good = false;
    for (const sec of (secrets || []).filter(Boolean)) {
      const exp = crypto.createHmac('sha256', sec).update(parts[0] + '.' + parts[1]).digest();
      if (exp.length === given.length && crypto.timingSafeEqual(exp, given)) { good = true; break; }
    }
    if (!good) return { ok: false, reason: 'bad_signature' };
    let c;
    try { c = JSON.parse(unb64u(parts[1]).toString('utf8')); } catch (e) { return { ok: false, reason: 'malformed' }; }
    if (!c || typeof c !== 'object' || typeof c.i !== 'string' || !c.i || !isIdList(c.p) || !isIdList(c.w)) return { ok: false, reason: 'malformed' };
    if (typeof c.e !== 'number' || !(c.e > nowSec)) return { ok: false, reason: 'expired' };
    if (c.c !== undefined && !isIdList(c.c)) return { ok: false, reason: 'malformed' };
    return { ok: true, claims: { i: c.i, u: (typeof c.u === 'string' && c.u) ? c.u : null, p: c.p, w: c.w, c: c.c || [], e: c.e, n: (typeof c.n === 'number') ? c.n : 1 } };
  }
  function sha256Hex(s) { return crypto.createHash('sha256').update(String(s)).digest('hex'); }
  function randomSecret(bytes) { return b64u(crypto.randomBytes(bytes || 32)); }
  function bearer(headers) {
    const h = headers || {};
    const a = String(h.authorization || h.Authorization || '');
    return a.startsWith('Bearer ') ? a.slice(7).trim() : '';
  }
  return { sign, verify, sha256Hex, randomSecret, bearer, b64u, unb64u };
})();
// CRAUTH-TOKEN-END
const RULE = {"appUser": ["appUserId"], "appUserRequired": ["appUserId"], "legacy": false};
const inItem = $input.first();
const wh = inItem.json;
const secrets = [$env.CR_AUTH_SECRET, $env.CR_AUTH_SECRET_PREV];
const compatUntil = Date.parse($env.CR_AUTH_COMPAT_UNTIL || '') || 0;
const nowMs = Date.now();
const token = crAuth.bearer(wh.headers);
let mode = 'session', claims = null, deny = null;
if (!token) {
  if (RULE.legacy && compatUntil > nowMs) mode = 'legacy';
  else deny = 'unauthorized:missing';
} else {
  const v = crAuth.verify(token, secrets, Math.floor(nowMs / 1000));
  if (!v.ok) deny = 'unauthorized:' + v.reason; else claims = v.claims;
}
const body = (wh.body && typeof wh.body === 'object') ? wh.body : {};
const isSentinel = (x) => x === undefined || x === null || x === '' || x === '-1';
const listOf = (v) => (Array.isArray(v) ? v : [v]);
const owned = (set, v) => listOf(v).every((x) => isSentinel(x) || (typeof x === 'string' && set.includes(x)));
if (!deny && mode === 'session') {
  for (const f of RULE.profiles || []) if (!owned(claims.p, body[f])) { deny = 'forbidden:' + f; break; }
  if (!deny) for (const f of RULE.workflows || []) if (!owned(claims.w, body[f])) { deny = 'forbidden:' + f; break; }
  if (!deny) for (const f of RULE.appUser || []) {
    const v = body[f];
    if (isSentinel(v)) {
      if ((RULE.appUserRequired || []).includes(f)) { deny = 'forbidden:' + f; break; }
      continue;
    }
    if (!claims.u || String(v) !== claims.u) { deny = 'forbidden:' + f; break; }
  }
}
return [{ json: { ...wh, crAuth: {
  ok: !deny, mode, reason: deny,
  installId: claims ? claims.i : null, appUserId: claims ? claims.u : null,
  profiles: claims ? claims.p : [], workflows: claims ? claims.w : [], claimPending: claims ? (claims.c || []) : [],
} }, ...(inItem.binary ? { binary: inItem.binary } : {}), pairedItem: { item: 0 } }];

// VERIFY IDENTITY / Validate (generated by Tools/n8n/build-verify-identity.py — edit there, never the JSON). The
// recipient and the install are the VERIFIED token's (crAuth) — every later node reads them from the gate, never from the
// body (the gate already refused a body whose appUserId is not the token's billing id, and a token without one). The
// original id the client names is a HINT only: a RevenueCat anonymous id, checked against RevenueCat's own alias list in
// Plan Heal — never a recipient, never a source by itself.
const wh = $input.first().json || {};
const a = wh.crAuth || {};
const b = (wh.body && typeof wh.body === 'object') ? wh.body : {};
const RC_ID = /^\$RCAnonymousID:[0-9a-f]{32}$/;
const u = typeof a.appUserId === 'string' ? a.appUserId : '';
const install = typeof a.installId === 'string' ? a.installId : '';
if (a.ok !== true || a.mode !== 'session' || !RC_ID.test(u) || !install) {
  return [{ json: { ok: false, error: 'bad_request', detail: 'identity' } }];
}
const raw = b.originalAppUserId;
let hint = null;
if (raw !== undefined && raw !== null && raw !== '') {
  if (typeof raw !== 'string' || !RC_ID.test(raw)) return [{ json: { ok: false, error: 'bad_request', detail: 'originalAppUserId' } }];
  if (raw !== u) hint = raw;   // the token's own id is no hint: RevenueCat's list alone decides
}
return [{ json: { ok: true, hint } }];

// VERIFY IDENTITY / Plan Heal (generated by Tools/n8n/build-verify-identity.py). RevenueCat's OWN list of the
// customer's ids (read with the server's secret key) decides what may be consolidated — never the client:
//   * the list must name the token's billing id itself (it describes THAT customer) — else rc_mismatch;
//   * the client's hint, when it named one, must be on the list — else hint_not_alias;
//   * every OTHER id on the list is consolidated INTO the token's id (RevenueCat Events' alias merge, run now instead of at
//     RevenueCat's next event) — none: no_aliases.
// A refusal writes nothing: Heal? lets only heal === true through.
const u = $('Auth Gate').first().json.crAuth.appUserId;
const hint = $('Validate').first().json.hint;
const body = $input.first().json.body || {};
const ids = [...new Set((Array.isArray(body.items) ? body.items : [])
  .map((x) => ((x && typeof x.id === 'string') ? x.id : ''))
  .filter((x) => x.length > 0 && x.length <= 128))];
const from = ids.filter((x) => x !== u);
// a refusal carries RevenueCat's ids minus the recipient for the support journal (Log Refusal, after the answer)
const refuse = (reason) => [{ json: { heal: false, reason, fromIds: JSON.stringify(from) } }];
if (!ids.includes(u)) return refuse('rc_mismatch');
if (hint && !ids.includes(hint)) return refuse('hint_not_alias');
if (from.length === 0) return refuse('no_aliases');
return [{ json: { heal: true, fromIds: JSON.stringify(from), aliases: from.length, truncated: !!body.next_page } }];

// VERIFY IDENTITY / Shape Response (generated by Tools/n8n/build-verify-identity.py). Heal runs behind
// continue-on-error + alwaysOutputData, so ONLY its positive row (verdict 'healed') is a success — an empty item, the input
// passed on or an error item is a fault (503), never «done».
const r = $input.first().json || {};
const plan = $('Plan Heal').first().json || {};
if (r.verdict !== 'healed') return [{ json: { success: false, reason: 'db_unavailable', _status: 503 } }];
return [{ json: { success: true, aliases: Number(plan.aliases) || 0, consolidated: Number(r.retired_rows) || 0,
  rekeyed: Number(r.rekeyed_rows) || 0, truncated: plan.truncated === true, _status: 200 } }];
